<template><el-dialog :model-value="modelValue" title="Provider" @close="$emit('update:modelValue',false)"><el-form :model="form"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="类型"><el-select v-model="form.providerType"><el-option v-for="x in types" :key="x" :value="x" :label="x"/></el-select></el-form-item><el-form-item label="Base URL"><el-input v-model="form.baseUrl"/></el-form-item><el-form-item label="API Key"><el-input v-model="form.apiKey" type="password" show-password :placeholder="value?.apiKeyConfigured?'已配置；留空保持原凭证':'请输入凭证'"/></el-form-item><el-collapse><el-collapse-item title="高级配置"><el-input v-model="form.configJson" type="textarea"/></el-collapse-item></el-collapse><el-button type="primary" @click="save">保存</el-button></el-form></el-dialog></template>
<script setup lang="ts">import {reactive,watch} from 'vue';import {AiModelApi,type ProviderVO} from '@/api/ai/model';const props=defineProps<{modelValue:boolean,value?:ProviderVO}>();const emit=defineEmits(['update:modelValue','saved']);const types=['QWEN','DEEPSEEK','DOUBAO'];const form=reactive<any>({name:'',code:'',providerType:'QWEN',baseUrl:'',apiKey:'',configJson:'{}',status:'ENABLED'});watch(()=>props.value,v=>Object.assign(form,v||{}, {apiKey:''}),{immediate:true});async function save(){const data={...form};if(props.value?.id){if(!data.apiKey) delete data.apiKey;await AiModelApi.updateProvider(props.value.id,data)}else await AiModelApi.createProvider(data);emit('saved');emit('update:modelValue',false)}</script>